import express from "express";
import { z } from "zod";
import Thread from "../models/Thread.js";
import getLLMResponse from "../utils/llm.js";
import ownerFilter from "../middleware/ownerFilter.js";

const router = express.Router();

// ── Zod schemas ──────────────────────────────────────────────────────────────

// UUID v4 pattern (generated by crypto.randomUUID on the frontend)
const uuidSchema = z.string().uuid("threadId must be a valid UUID");

const chatSchema = z.object({
    threadId: uuidSchema,
    message: z.string()
        .trim()   // must come BEFORE min/max, otherwise "   " passes min(1) and is saved as ""
        .min(1, "Message cannot be empty")
        .max(4000, "Message cannot exceed 4000 characters")
});

const PAGE_SIZE_DEFAULT = 20;
const PAGE_SIZE_MAX = 100;
const OBJECT_ID_RE = /^[0-9a-f]{24}$/i;

// Cursor format: "<updatedAt ISO string>|<thread _id>".
// updatedAt alone is not unique, so _id is the tiebreaker; without it a page boundary
// between two threads with the same updatedAt would silently skip one of them.
const parseCursor = (raw) => {
    if (typeof raw !== "string") return null;   // ?cursor=a&cursor=b arrives as an array
    const [iso, id] = raw.split("|");
    const date = new Date(iso);
    if (Number.isNaN(date.getTime()) || !OBJECT_ID_RE.test(id || "")) return null;
    return { date, id };
};

// ── GET /thread – list the caller's threads (newest first, paginated) ────────
// ?limit=20&cursor=<updatedAt>|<_id>  (both values come from the LAST item of the previous page)

router.get("/thread", async (req, res, next) => {
    try {
        const owner = ownerFilter(req); // throws 403/400 if identity is missing/invalid

        const requested = Number.parseInt(req.query.limit, 10);
        const limit = Math.min(Math.max(requested || PAGE_SIZE_DEFAULT, 1), PAGE_SIZE_MAX);

        const query = { ...owner };
        if (req.query.cursor !== undefined) {
            const cursor = parseCursor(req.query.cursor);
            if (!cursor) {
                return res.status(400).json({ error: "Invalid cursor" });
            }
            query.$or = [
                { updatedAt: { $lt: cursor.date } },
                { updatedAt: cursor.date, _id: { $lt: cursor.id } }
            ];
        }

        const threads = await Thread
            .find(query)
            .sort({ updatedAt: -1, _id: -1 })
            .limit(limit)
            .select("threadId title updatedAt");

        res.json(threads);
    } catch (error) {
        next(error);
    }
});

// ── GET /thread/:threadId – load messages for a specific thread ──────────────

router.get("/thread/:threadId", async (req, res, next) => {
    const parsed = uuidSchema.safeParse(req.params.threadId);
    if (!parsed.success) {
        return res.status(400).json({ error: parsed.error.issues[0].message });
    }

    try {
        const owner = ownerFilter(req);
        // Scope by both threadId AND owner — wrong owner gets a 404, not a 403,
        // to avoid revealing that the thread exists.
        const thread = await Thread.findOne({ threadId: req.params.threadId, ...owner });
        if (!thread) {
            return res.status(404).json({ error: "Thread not found" });
        }
        res.json(thread.messages);
    } catch (error) {
        next(error);
    }
});

// ── DELETE /thread/:threadId – delete a thread owned by the caller ───────────

router.delete("/thread/:threadId", async (req, res, next) => {
    const parsed = uuidSchema.safeParse(req.params.threadId);
    if (!parsed.success) {
        return res.status(400).json({ error: parsed.error.issues[0].message });
    }

    try {
        const owner = ownerFilter(req);
        const deleted = await Thread.findOneAndDelete({
            threadId: req.params.threadId,
            ...owner
        });
        if (!deleted) {
            return res.status(404).json({ error: "Thread not found" });
        }
        res.json({ success: "Thread deleted successfully" });
    } catch (error) {
        next(error);
    }
});

// ── POST /chat – send a message and receive an LLM reply ─────────────────────

router.post("/chat", async (req, res, next) => {
    const parsed = chatSchema.safeParse(req.body);
    if (!parsed.success) {
        return res.status(400).json({ error: parsed.error.issues[0].message });
    }

    const { threadId, message } = parsed.data;

    try {
        const owner = ownerFilter(req);

        let thread = await Thread.findOne({ threadId, ...owner });

        if (!thread) {
            // threadId is globally unique. If it already exists under ANOTHER owner, stop here:
            // creating it would fail on the unique index only after an LLM call was already paid for,
            // and the 500-vs-200 difference would reveal that someone else's thread exists.
            if (await Thread.exists({ threadId })) {
                return res.status(404).json({ error: "Thread not found" });
            }
            // Create a new thread scoped to this owner only
            thread = new Thread({
                threadId,
                ...owner, // sets either userId or guestId
                title: message.slice(0, 40),
                messages: [{ role: "user", content: message }]
            });
        } else {
            thread.messages.push({ role: "user", content: message });
        }

        // Send full conversation history so the LLM has multi-turn context
        const assistantReply = await getLLMResponse(thread.messages);
        thread.messages.push({ role: "assistant", content: assistantReply });
        await thread.save();

        res.json({ reply: assistantReply });
    } catch (error) {
        // Two simultaneous first messages with the same new threadId: the loser hits the unique index.
        if (error?.code === 11000) {
            return res.status(409).json({ error: "Thread already exists" });
        }
        next(error);
    }
});

export default router;
